unsafe fn generate(n:usize,open:usize,close:usize,path:&mut [u8;12],out:*mut u8,index:&mut usize){if open+close==2*n{for i in 0..2*n{*out.add(2+*index*(2*n)+i)=path[i]}*index+=1;return}if open<n{path[open+close]=b'(';generate(n,open+1,close,path,out,index)}if close<open{path[open+close]=b')';generate(n,open,close+1,path,out,index)}}
#[no_mangle]
pub unsafe extern "C" fn parentheses_generator(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n!=1{return -1}let pairs=*v;if !(0..=6).contains(&pairs){return -1}let counts=[1usize,1,2,5,14,42,132];let k=pairs as usize;let need=2+counts[k]*2*k;if need>cap||out.is_null(){return -2}*out=counts[k] as u8;*out.add(1)=(counts[k]>>8)as u8;let mut idx=0;let mut path=[0u8;12];generate(k,0,0,&mut path,out,&mut idx);need as i64}
